// Some portions generated by Codex
package org.eclipse.rdf4j.workbench.security;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.PosixFilePermission;
import java.security.SecureRandom;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class WorkbenchCredentialKeyringSecurityTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void createsOwnerOnlyKeyringAndRotatesExpiredActiveKey() throws Exception {
		Path keyFile = temporaryDirectory.resolve("credentials.keys");
		Object initial = open(keyFile, false, Instant.parse("2026-01-01T00:00:00Z"));
		String initialKey = accessor(initial, "activeKeyId");

		assertThat(Files.readString(keyFile)).doesNotContain("AES/GCM");
		assertThat(Files.getPosixFilePermissions(keyFile))
				.isEqualTo(Set.of(PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE));

		Object rotated = open(keyFile, false, Instant.parse("2026-04-02T00:00:00Z"));
		assertThat((String) accessor(rotated, "activeKeyId")).isNotEqualTo(initialKey);
		assertThat((Map<String, ?>) accessor(rotated, "keys")).containsKey(initialKey).hasSize(2);
	}

	@Test
	void rejectsExternalKeyringWithGroupReadablePermissions() throws Exception {
		Path keyFile = temporaryDirectory.resolve("shared.keys");
		open(keyFile, false, Instant.parse("2026-01-01T00:00:00Z"));
		Files.setPosixFilePermissions(keyFile,
				Set.of(PosixFilePermission.OWNER_READ, PosixFilePermission.OWNER_WRITE,
						PosixFilePermission.GROUP_READ));

		assertThatThrownBy(() -> open(keyFile, true, Instant.parse("2026-01-02T00:00:00Z")))
				.isInstanceOf(InvocationTargetException.class)
				.hasCauseInstanceOf(SecurityException.class);
	}

	private static Object open(Path file, boolean external, Instant instant) throws Exception {
		Class<?> type = Class.forName("org.eclipse.rdf4j.workbench.security.WorkbenchCredentialKeyring");
		Method method = type.getMethod("open", Path.class, boolean.class, Clock.class, SecureRandom.class,
				Duration.class);
		return method.invoke(null, file, external, Clock.fixed(instant, ZoneOffset.UTC), new SecureRandom(),
				Duration.ofDays(30));
	}

	@SuppressWarnings("unchecked")
	private static <T> T accessor(Object target, String name) throws Exception {
		return (T) target.getClass().getMethod(name).invoke(target);
	}
}
